#include <automation/workflows/automation_runtime.hpp>
#include <algorithm>
namespace rebuntu::workflow {bool AutomationRuntime::register_automaton(Automaton a){return automata_.emplace(a.id,std::move(a)).second;}bool AutomationRuntime::remove(std::string_view id){return automata_.erase(std::string(id))>0;}std::vector<std::string>AutomationRuntime::discover()const{std::vector<std::string>o;for(auto&[k,v]:automata_)o.push_back(k);return o;}std::optional<RunEvidence>AutomationRuntime::trigger(std::string_view id){auto it=automata_.find(std::string(id));if(it==automata_.end()||!it->second.policy.enabled)return{};auto&a=it->second;auto now=std::chrono::steady_clock::now();if(a.last_run.time_since_epoch().count()&&now-a.last_run<a.policy.cooldown){a.state=RunState::cooldown;return RunEvidence{a.id,a.state,0,"cooldown"};}a.state=RunState::running;bool ok=false;unsigned attempt=0;for(;attempt<=a.policy.max_retries&&!ok;++attempt){try{ok=a.action&&a.action();}catch(...){ok=false;}}a.last_run=now;a.state=ok?RunState::succeeded:RunState::failed;if(!ok)++a.failures;RunEvidence ev{a.id,a.state,attempt,ok?"verified success":"action failed after retries"};evidence_.push_back(ev);return ev;}bool WorkflowRuntime::run(const Workflow&w){completed_.clear();std::vector<std::string>pending;for(auto&s:w.steps)pending.push_back(s.id);size_t guard=w.steps.size()+1;while(!pending.empty()&&guard--){bool progress=false;for(auto&s:w.steps){if(std::find(pending.begin(),pending.end(),s.id)==pending.end())continue;bool deps=std::all_of(s.depends_on.begin(),s.depends_on.end(),[&](auto&d){return std::find(completed_.begin(),completed_.end(),d)!=completed_.end();});if(deps){if(!s.action||!s.action())return false;completed_.push_back(s.id);pending.erase(std::remove(pending.begin(),pending.end(),s.id),pending.end());progress=true;}}if(!progress)return false;}return pending.empty();}}
